        aFoldValue |= static_cast<std::uint32_t>(aSourceLaneC[aIndexC]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aSourceLaneD[aIndexD]) << 16U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);
